public static void main(String[] args) {
    test("a miss loads once, the next get is a hit", () -> {
        var backend = new Backend();
        var c = new LoadingCache<String, String>(2, backend);
        eq(c.get("a"), "A");
        eq(c.get("a"), "A");
        eq(backend.calls, List.of("a"));
        eq(c.stats(), new Stats(1, 1, 1, 0));
    });
    test("evicts the least recently used key and counts it", () -> {
        var backend = new Backend();
        var c = new LoadingCache<String, String>(2, backend);
        c.get("a");
        c.get("b");
        c.get("a");
        c.get("c");
        c.get("a");
        c.get("b");
        eq(backend.calls, List.of("a", "b", "c", "b"));
        eq(c.stats(), new Stats(2, 4, 4, 2));
    });
    test("a failing loader propagates and caches nothing", () -> {
        var backend = new Backend();
        var c = new LoadingCache<String, String>(2, backend);
        raises(IllegalArgumentException.class, () -> c.get("boom"), "boom");
        raises(IllegalArgumentException.class, () -> c.get("boom"));
        eq(backend.calls, List.of("boom", "boom"));
        eq(c.stats(), new Stats(0, 2, 0, 0));
    });
    test("a null from the loader is an IllegalStateException", () -> {
        var backend = new Backend();
        var c = new LoadingCache<String, String>(2, backend);
        raises(IllegalStateException.class, () -> c.get("ghost"));
        raises(IllegalStateException.class, () -> c.get("ghost"));
        eq(backend.calls.size(), 2);
        eq(c.stats(), new Stats(0, 2, 0, 0));
    });
    test("hitRate is hits over requests", () -> {
        var c = new LoadingCache<String, String>(2, new Backend());
        c.get("a");
        c.get("a");
        c.get("a");
        c.get("a");
        approx(c.hitRate(), 0.75, 1e-9);
    });
    test("hitRate is 0.0 before any request", () -> {
        var c = new LoadingCache<String, String>(2, new Backend());
        eq(c.hitRate(), 0.0);
        eq(c.stats(), new Stats(0, 0, 0, 0));
    });
    test("invalidate forces a reload and is not an eviction", () -> {
        var backend = new Backend();
        var c = new LoadingCache<String, String>(2, backend);
        c.get("a");
        c.invalidate("a");
        c.invalidate("never-loaded");
        c.get("a");
        eq(backend.calls, List.of("a", "a"));
        eq(c.stats(), new Stats(0, 2, 2, 0));
    });
    test("refuses a capacity below one", () -> {
        raises(IllegalArgumentException.class, () -> new LoadingCache<String, String>(0, new Backend()));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("a found value is cached for the positive ttl", () -> {
        var users = new Users();
        users.rows.put("ada", "Ada Lovelace");
        var clock = new FakeClock();
        var c = new NegativeCache(users, 1_000, 100, clock);
        eq(c.find("ada"), Optional.of("Ada Lovelace"));
        clock.now = 999;
        eq(c.find("ada"), Optional.of("Ada Lovelace"));
        eq(users.calls, 1);
        clock.now = 1_000;
        c.find("ada");
        eq(users.calls, 2);
    });
    test("a miss is cached for the shorter negative ttl", () -> {
        var users = new Users();
        var clock = new FakeClock();
        var c = new NegativeCache(users, 1_000, 100, clock);
        eq(c.find("bob"), Optional.empty());
        clock.now = 99;
        eq(c.find("bob"), Optional.empty());
        eq(users.calls, 1);
        clock.now = 100;
        c.find("bob");
        eq(users.calls, 2);
    });
    test("a key that appears later is found once the miss expires", () -> {
        var users = new Users();
        var clock = new FakeClock();
        var c = new NegativeCache(users, 1_000, 100, clock);
        c.find("bob");
        users.rows.put("bob", "Bob");
        clock.now = 50;
        eq(c.find("bob"), Optional.empty());
        clock.now = 100;
        eq(c.find("bob"), Optional.of("Bob"));
    });
    test("a backend error propagates and is not cached", () -> {
        var users = new Users();
        users.rows.put("ada", "Ada Lovelace");
        var clock = new FakeClock();
        var c = new NegativeCache(users, 1_000, 100, clock);
        users.down = true;
        raises(IllegalStateException.class, () -> c.find("ada"), "timed out");
        users.down = false;
        eq(c.find("ada"), Optional.of("Ada Lovelace"));
        eq(users.calls, 2);
    });
    test("onCreated replaces a remembered miss", () -> {
        var users = new Users();
        var clock = new FakeClock();
        var c = new NegativeCache(users, 1_000, 100, clock);
        c.find("bob");
        users.rows.put("bob", "Bob");
        c.onCreated("bob", "Bob");
        eq(c.find("bob"), Optional.of("Bob"));
        eq(users.calls, 1);
    });
    test("onCreated values last the positive ttl", () -> {
        var users = new Users();
        var clock = new FakeClock();
        var c = new NegativeCache(users, 1_000, 100, clock);
        clock.now = 10;
        c.onCreated("eve", "Eve");
        clock.now = 1_009;
        eq(c.find("eve"), Optional.of("Eve"));
        eq(users.calls, 0);
    });
    test("invalidate drops either kind of entry", () -> {
        var users = new Users();
        users.rows.put("ada", "Ada Lovelace");
        var clock = new FakeClock();
        var c = new NegativeCache(users, 1_000, 100, clock);
        c.find("ada");
        c.find("bob");
        c.invalidate("ada");
        c.invalidate("bob");
        c.find("ada");
        c.find("bob");
        eq(users.calls, 4);
    });
    test("refuses a ttl below one millisecond", () -> {
        var clock = new FakeClock();
        raises(IllegalArgumentException.class, () -> new NegativeCache(new Users(), 0, 100, clock));
        raises(IllegalArgumentException.class, () -> new NegativeCache(new Users(), 100, 0, clock));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("invalidate reports EXPLICIT with the value", () -> {
        var log = new Log();
        var c = new ListeningCache<String, Integer>(2, 100, new FakeClock(), log);
        c.put("a", 1);
        c.invalidate("a");
        c.invalidate("a");
        c.invalidate("never");
        eq(log.events, List.of("a=1 EXPLICIT"));
        eq(c.get("a"), Optional.empty());
    });
    test("replacing reports REPLACED with the old value", () -> {
        var log = new Log();
        var c = new ListeningCache<String, Integer>(2, 100, new FakeClock(), log);
        c.put("a", 1);
        c.put("a", 2);
        eq(log.events, List.of("a=1 REPLACED"));
        eq(c.get("a"), Optional.of(2));
    });
    test("overflow evicts the least recently used with SIZE", () -> {
        var log = new Log();
        var c = new ListeningCache<String, Integer>(2, 100, new FakeClock(), log);
        c.put("a", 1);
        c.put("b", 2);
        c.get("a");
        c.put("c", 3);
        eq(log.events, List.of("b=2 SIZE"));
        eq(c.get("a"), Optional.of(1));
        eq(c.get("c"), Optional.of(3));
    });
    test("dead entries leave before anyone is evicted for size", () -> {
        var log = new Log();
        var clock = new FakeClock();
        var c = new ListeningCache<String, Integer>(2, 100, clock, log);
        c.put("a", 1);
        clock.now = 50;
        c.put("b", 2);
        clock.now = 60;
        c.get("a");
        clock.now = 110;
        c.put("c", 3);
        eq(log.events, List.of("a=1 EXPIRED"));
        eq(c.get("b"), Optional.of(2));
        eq(c.get("c"), Optional.of(3));
    });
    test("several dead entries are reported least recently used first", () -> {
        var log = new Log();
        var clock = new FakeClock();
        var c = new ListeningCache<String, Integer>(2, 100, clock, log);
        c.put("a", 1);
        c.put("b", 2);
        c.get("a");
        clock.now = 500;
        c.put("c", 3);
        eq(log.events, List.of("b=2 EXPIRED", "a=1 EXPIRED"));
    });
    test("touching an expired entry reports EXPIRED", () -> {
        var log = new Log();
        var clock = new FakeClock();
        var c = new ListeningCache<String, Integer>(2, 100, clock, log);
        c.put("a", 1);
        c.put("b", 2);
        clock.now = 100;
        eq(c.get("a"), Optional.empty());
        eq(c.get("a"), Optional.empty());
        c.invalidate("b");
        eq(log.events, List.of("a=1 EXPIRED", "b=2 EXPIRED"));
    });
    test("putting over an expired key reports EXPIRED, not REPLACED", () -> {
        var log = new Log();
        var clock = new FakeClock();
        var c = new ListeningCache<String, Integer>(2, 100, clock, log);
        c.put("a", 1);
        clock.now = 100;
        c.put("a", 2);
        eq(log.events, List.of("a=1 EXPIRED"));
        eq(c.get("a"), Optional.of(2));
    });
    test("a put that fits leaves dead entries alone", () -> {
        var log = new Log();
        var clock = new FakeClock();
        var c = new ListeningCache<String, Integer>(3, 100, clock, log);
        c.put("a", 1);
        clock.now = 100;
        c.put("b", 2);
        c.put("c", 3);
        eq(log.events, List.of());
        eq(c.get("a"), Optional.empty());
        eq(log.events, List.of("a=1 EXPIRED"));
    });
    test("a throwing listener does not break the cache", () -> {
        var c = new ListeningCache<String, Integer>(1, 100, new FakeClock(),
            (k, v, cause) -> { throw new IllegalStateException("listener bug"); });
        c.put("a", 1);
        c.put("b", 2);
        c.put("b", 3);
        eq(c.get("a"), Optional.empty());
        eq(c.get("b"), Optional.of(3));
        eq(c.listenerErrors(), 2);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("a miss is empty and has frequency 0", () -> {
        var c = new LfuCache<String, Integer>(2);
        eq(c.get("a"), Optional.empty());
        eq(c.frequency("a"), 0);
        c.put("a", 1);
        eq(c.frequency("a"), 1);
        eq(c.get("a"), Optional.of(1));
        eq(c.frequency("a"), 2);
    });
    test("evicts the least frequently used key", () -> {
        var c = new LfuCache<String, Integer>(2);
        c.put("a", 1);
        c.put("b", 2);
        c.get("a");
        c.put("c", 3);
        eq(c.frequency("b"), 0);
        eq(c.get("a"), Optional.of(1));
        eq(c.get("c"), Optional.of(3));
    });
    test("ties go to the least recently used, not the oldest insert", () -> {
        var c = new LfuCache<String, Integer>(2);
        c.put("a", 1);
        c.put("b", 2);
        c.get("b");
        c.get("a");
        c.put("c", 3);
        eq(c.frequency("b"), 0);
        eq(c.frequency("a"), 2);
    });
    test("a newcomer is the next victim even when others are hot", () -> {
        var c = new LfuCache<String, Integer>(2);
        c.put("a", 1);
        c.get("a");
        c.get("a");
        c.put("b", 2);
        c.put("c", 3);
        eq(c.frequency("b"), 0);
        c.put("d", 4);
        eq(c.frequency("c"), 0);
        eq(c.frequency("a"), 3);
        eq(c.frequency("d"), 1);
    });
    test("the minimum moves up when its last key is promoted", () -> {
        var c = new LfuCache<String, Integer>(2);
        c.put("a", 1);
        c.put("b", 2);
        c.get("a");
        c.get("b");
        c.get("a");
        c.put("c", 3);
        eq(c.frequency("b"), 0);
        eq(c.frequency("a"), 3);
        eq(c.frequency("c"), 1);
    });
    test("emptying a bucket above the minimum leaves the minimum alone", () -> {
        var c = new LfuCache<String, Integer>(2);
        c.put("a", 1);
        c.get("a");
        c.put("b", 2);
        c.get("a");
        c.put("c", 3);
        eq(c.frequency("b"), 0);
        eq(c.frequency("a"), 3);
        eq(c.frequency("c"), 1);
    });
    test("put on an existing key replaces it and counts as a use", () -> {
        var c = new LfuCache<String, Integer>(2);
        c.put("a", 1);
        c.put("b", 2);
        c.put("a", 9);
        eq(c.frequency("a"), 2);
        c.put("c", 3);
        eq(c.get("a"), Optional.of(9));
        eq(c.frequency("b"), 0);
    });
    test("an evicted key starts over at frequency one", () -> {
        var c = new LfuCache<String, Integer>(1);
        c.put("a", 1);
        c.get("a");
        c.get("a");
        c.put("b", 2);
        eq(c.frequency("a"), 0);
        c.put("a", 5);
        eq(c.frequency("a"), 1);
        eq(c.get("b"), Optional.empty());
    });
    test("refuses a capacity below one", () -> {
        raises(IllegalArgumentException.class, () -> new LfuCache<String, Integer>(0));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("gets during a flight call the loader once", () -> {
        var db = new Backend();
        var sf = new SingleFlight<String, String>(db);
        sf.get("k");
        sf.get("k");
        sf.get("k");
        eq(db.calls, List.of("k"));
        eq(sf.inFlight(), 1);
    });
    test("every waiter gets the result when the flight lands", () -> {
        var db = new Backend();
        var sf = new SingleFlight<String, String>(db);
        var a = sf.get("k");
        var b = sf.get("k");
        eq(a.isDone(), false);
        db.finish("k");
        eq(a.isDone() && b.isDone(), true);
        eq(a.join(), "row k");
        eq(b.join(), "row k");
    });
    test("different keys fly independently", () -> {
        var db = new Backend();
        var sf = new SingleFlight<String, String>(db);
        var a = sf.get("a");
        var b = sf.get("b");
        eq(db.calls, List.of("a", "b"));
        eq(sf.inFlight(), 2);
        db.finish("b");
        eq(b.join(), "row b");
        eq(a.isDone(), false);
        eq(sf.inFlight(), 1);
    });
    test("it is not a cache: after landing the next get loads again", () -> {
        var db = new Backend();
        var sf = new SingleFlight<String, String>(db);
        sf.get("k");
        db.finish("k");
        eq(sf.inFlight(), 0);
        sf.get("k");
        eq(db.calls, List.of("k", "k"));
    });
    test("a failure reaches every waiter and the next get retries", () -> {
        var db = new Backend();
        var sf = new SingleFlight<String, String>(db);
